import { buildLlmsTxt } from '@/lib/seo/llms';
import { TARGET_CLUSTERS } from '@/lib/seo/targets';
import { getPublicStatsOrNull } from '@/lib/stats/site-stats';

// /llms.txt (SEO Mission 3, part F.4), generated by lib/seo/llms.ts from the site stats
// function and the cluster owners (lib/seo/targets.ts, mirrored from docs/seo/TARGETS.md).
//
// CALIBRATION, kept from W9a so nobody over-invests later: llms.txt is "a cheap experiment,
// not a core ranking lever". It earns its place by being true: the counts are the live ones,
// the same as every page on the same day (the stats function caches them for six hours), and
// when they cannot be read the file says "hundreds of" rather than an invented number.
//
// Hourly ISR, like the home page. No llms-full.txt.
export const revalidate = 3600;

export async function GET(): Promise<Response> {
  const body = buildLlmsTxt(await getPublicStatsOrNull(), TARGET_CLUSTERS);
  return new Response(body, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
}
